-- Run as postgres after all migrations. Synthetic records and storage metadata roll back.
begin;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;end$$;
create function pg_temp.denied(statement text,state text default 'P0001') returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate<>state then raise exception 'FAIL: expected %, got %: %',state,sqlstate,sqlerrm;end if;return;end;raise exception 'FAIL: unexpectedly allowed: %',statement;end$$;
create temporary table ids(key text primary key,id uuid);
grant all on ids to authenticated;
create function pg_temp.scan(target uuid) returns uuid language plpgsql as $$declare q jsonb;begin q:=public.get_handoff_qr(target,(select revision from public.loans where id=target));perform public.simulate_locker_scan((q->>'id')::uuid);return(q->>'id')::uuid;end$$;
create function pg_temp.photo(target uuid,stage text,checks text[] default '{}') returns void language plpgsql as $$declare path text:=target::text||'/'||stage||'/proof.jpg';begin
 insert into storage.objects(bucket_id,name,owner_id,metadata) values('loan-verification',path,auth.uid()::text,'{"mimetype":"image/jpeg","size":1}') on conflict do nothing;
 perform public.record_handoff_photo(target,stage,path,checks);
end$$;
insert into auth.users(id,raw_user_meta_data) values
 ('30000000-0000-0000-0000-000000000001','{"display_name":"Test owner"}'),
 ('30000000-0000-0000-0000-000000000002','{"display_name":"Test borrower"}'),
 ('30000000-0000-0000-0000-000000000003','{"display_name":"Test outsider"}');
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select pg_temp.ok((select count(*)=10 from public.lockers),'ten fixed lockers');
insert into ids select 'item',id from public.create_item('Frame test','description',array['Tools','tools'],array[1,2]);
select pg_temp.ok((select category_tags=array['tools'] from public.items where id=(select id from ids where key='item')),'tag normalization');
select pg_temp.ok((select count(*)=2 from public.item_lockers where item_id=(select id from ids where key='item')),'item lockers');
insert into public.friendships(requester_id,recipient_id) values(auth.uid(),'30000000-0000-0000-0000-000000000002');
insert into ids select 'chat',id from public.chats where false;
insert into public.chats(user_one_id,user_two_id) values(auth.uid(),'30000000-0000-0000-0000-000000000002') returning id;
insert into ids select 'chat',id from public.chats where user_one_id=auth.uid() and user_two_id='30000000-0000-0000-0000-000000000002' limit 1;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000002',true);
select pg_temp.denied($q$select public.create_loan((select id from ids where key='item'),current_date,current_date+2,1)$q$);
update public.friendships set status='accepted' where recipient_id=auth.uid() and requester_id='30000000-0000-0000-0000-000000000001';
insert into ids select 'loan',id from public.create_loan((select id from ids where key='item'),current_date,current_date+2,1);
select pg_temp.ok((select lifecycle_status='created' from public.loan_catalog where id=(select id from ids where key='loan')),'borrower creates unapproved request');
select pg_temp.denied($q$select public.create_loan((select id from ids where key='item'),current_date+2,current_date+4,1)$q$,'23P01');
select pg_temp.denied($q$select public.get_handoff_qr((select id from ids where key='loan'),1)$q$);
select pg_temp.denied($q$select public.approve_loan((select id from ids where key='loan'),1)$q$);
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select public.approve_loan((select id from ids where key='loan'),1);
insert into ids select 'staleQR',(public.get_handoff_qr((select id from ids where key='loan'),1)->>'id')::uuid;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000002',true);
select public.modify_loan((select id from ids where key='loan'),current_date,current_date+3,2,1);
select pg_temp.ok((select lifecycle_status='created' and revision=2 from public.loan_catalog where id=(select id from ids where key='loan')),'edit resets approval');
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select pg_temp.denied($q$select public.simulate_locker_scan((select id from ids where key='staleQR'))$q$);
select public.approve_loan((select id from ids where key='loan'),2);
insert into ids select 'scanQR',pg_temp.scan((select id from ids where key='loan'));
select public.simulate_locker_scan((select id from ids where key='scanQR'));
select pg_temp.ok((select handoff_phase='ready_for_borrower_collection' and pending_photo='owner_dropoff' from public.loan_catalog where id=(select id from ids where key='loan')),'owner bypass advances before photo; retry idempotent');
select pg_temp.denied($q$select public.get_handoff_qr((select id from ids where key='loan'),2)$q$);
select pg_temp.photo((select id from ids where key='loan'),'owner_dropoff');
select public.record_handoff_photo((select id from ids where key='loan'),'owner_dropoff',(select id::text from ids where key='loan')||'/owner_dropoff/proof.jpg');
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000003',true);
select pg_temp.ok(exists(select 1 from public.item_catalog where id=(select id from ids where key='item') and status='ready_for_collection'),'nonfriend reads public item status');
select pg_temp.ok(not exists(select 1 from public.loans where id=(select id from ids where key='loan')),'outsider cannot read loan');
select pg_temp.ok(not exists(select 1 from storage.objects where bucket_id='loan-verification' and split_part(name,'/',1)=(select id::text from ids where key='loan')),'outsider cannot read proof');
select pg_temp.denied($q$select public.get_handoff_qr((select id from ids where key='loan'),2)$q$);
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000002',true);
select pg_temp.scan((select id from ids where key='loan'));
select pg_temp.ok((select lifecycle_status='on_loan' and pending_photo='borrower_pickup' from public.loan_catalog where id=(select id from ids where key='loan')),'borrower bypass marks on-loan before photo');
select pg_temp.denied($q$select public.cancel_loan((select id from ids where key='loan'),2)$q$);
select pg_temp.denied($q$select public.modify_loan((select id from ids where key='loan'),current_date,current_date+5,2,2)$q$);
select pg_temp.photo((select id from ids where key='loan'),'borrower_pickup');
select pg_temp.scan((select id from ids where key='loan'));
select pg_temp.ok((select handoff_phase='ready_for_owner_collection' and lifecycle_status='on_loan' from public.loan_catalog where id=(select id from ids where key='loan')),'borrower return is ready for owner collection');
select pg_temp.photo((select id from ids where key='loan'),'borrower_dropoff');
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select pg_temp.scan((select id from ids where key='loan'));
select pg_temp.ok((select lifecycle_status='returned' and temporal_status='past' and pending_photo='owner_pickup' from public.loan_catalog where id=(select id from ids where key='loan')),'owner bypass completes loan immediately');
select pg_temp.denied($q$select pg_temp.photo((select id from ids where key='loan'),'owner_pickup')$q$);
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000002',true);
select pg_temp.denied($q$select public.save_review((select id from ids where key='loan'),'Review',array['Compliment 1'])$q$);
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select pg_temp.photo((select id from ids where key='loan'),'owner_pickup',array['item','parts','condition']);
select pg_temp.ok((select pending_photo is null from public.loan_catalog where id=(select id from ids where key='loan')),'final proof completes evidence');
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000002',true);
insert into ids select 'review',id from public.save_review((select id from ids where key='loan'),'Great',array['Compliment 1']);
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000003',true);
select pg_temp.ok(jsonb_array_length(public.get_reviews((select id from ids where key='item')))=1,'all authenticated users read item review');
select pg_temp.ok(not(public.get_reviews((select id from ids where key='item'))->0 ? 'loan_id'),'public review omits private loan ID');
select pg_temp.denied($q$select public.delete_review((select id from ids where key='review'))$q$);
select pg_temp.ok(not exists(select 1 from public.messages where chat_id=(select id from ids where key='chat')),'outsider chat access denied');
select pg_temp.denied($q$select public.send_message((select id from ids where key='chat'),'no','30000000-0000-0000-0000-000000000010')$q$);
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000002',true);
select public.delete_review((select id from ids where key='review'));
select pg_temp.ok((select lifecycle_status='returned' and temporal_status='past' from public.loan_catalog where id=(select id from ids where key='loan')),'deleting review never reopens loan');
select pg_temp.ok(jsonb_array_length(public.get_reviews((select id from ids where key='item')))=0,'review removed');
select public.send_message((select id from ids where key='chat'),'Hello','30000000-0000-0000-0000-000000000010');
select public.send_message((select id from ids where key='chat'),'Hello','30000000-0000-0000-0000-000000000010');
select pg_temp.ok((select count(*)=1 from public.messages where chat_id=(select id from ids where key='chat')),'message retries deduplicated');
insert into storage.objects(bucket_id,name,owner_id,metadata) values('chat-images',(select id::text from ids where key='chat')||'/'||auth.uid()||'/test.jpg',auth.uid()::text,'{"mimetype":"image/jpeg","size":1}');
select public.send_message((select id from ids where key='chat'),'','30000000-0000-0000-0000-000000000011',(select id::text from ids where key='chat')||'/'||auth.uid()||'/test.jpg');
select pg_temp.ok((select count(*)=2 from public.messages where chat_id=(select id from ids where key='chat')),'image-only chat message');
-- Cancellation releases reservations while retaining the cancelled record.
insert into ids select 'cancel',id from public.create_loan((select id from ids where key='item'),current_date+20,current_date+21,1);
select public.cancel_loan((select id from ids where key='cancel'),1);
select public.create_loan((select id from ids where key='item'),current_date+20,current_date+21,1);
select pg_temp.ok((select cancelled_at is not null from public.loans where id=(select id from ids where key='cancel')),'cancellation retains history');
reset role;
set local role anon;
select pg_temp.denied('select * from public.lockers','42501');
select pg_temp.denied('select public.get_reviews()','42501');
reset role;
rollback;
select 'Feature frame integration checks passed; all fixtures rolled back.' as result;
